// Explicit env: PLAYWRIGHT_MODULE, GITDASH_TEST_ORIGIN, GITDASH_TEST_OUTPUT, GITDASH_TEST_FIXTURE.
const assert=require('node:assert/strict'),fs=require('node:fs/promises');
const {chromium}=require(process.env.PLAYWRIGHT_MODULE);
(async()=>{
 const fixture=JSON.parse(await fs.readFile(process.env.GITDASH_TEST_FIXTURE,'utf8'));
 const origin=process.env.GITDASH_TEST_ORIGIN,output=process.env.GITDASH_TEST_OUTPUT;assert.ok(origin&&output);
 const browser=await chromium.launch({headless:true});const ctx=await browser.newContext({viewport:{width:1440,height:1000},permissions:['clipboard-read','clipboard-write'],timezoneId:'Asia/Tokyo'});
 const page=await ctx.newPage();page.setDefaultTimeout(20000);const errors=[],passed=[];page.on('pageerror',e=>errors.push(e.message));
 const clip=()=>page.evaluate(()=>navigator.clipboard.readText());
 const projectUrl=`${origin}/project?path=${encodeURIComponent(fixture.path)}&tab=info&range=current`;
 const download=async(scope,name)=>{const pending=page.waitForEvent('download');await scope.getByRole('button',{name,exact:true}).click();return fs.readFile(await(await pending).path(),'utf8');};
 const capture=async(scope,name)=>{await scope.locator('summary').first().scrollIntoViewIfNeeded();await page.screenshot({path:`${output}/${name}.png`});await page.setViewportSize({width:390,height:844});await scope.locator('summary').first().scrollIntoViewIfNeeded();await page.screenshot({path:`${output}/${name}-mobile.png`});assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),`${name}: mobile overflow`);await page.setViewportSize({width:1440,height:1000});};
 await fs.mkdir(output,{recursive:true});
 try{
  await page.goto(projectUrl);
  const tags=page.locator('.tag-explorer');await tags.locator('summary').first().click();await tags.locator('tbody tr').first().waitFor();assert.equal(await tags.locator('tbody tr').count(),3);
  await tags.getByLabel('タグの種類で絞り込み').selectOption('lightweight');assert.equal(await tags.locator('tbody tr').count(),1);assert.ok((await tags.locator('tbody').innerText()).includes('v1.0'));
  await tags.getByLabel('タグの種類で絞り込み').selectOption('all');await tags.getByRole('searchbox',{name:'タグ名を完全一致で検索',exact:true}).fill('v2');assert.equal(await tags.locator('tbody tr').count(),0);
  await tags.getByRole('searchbox',{name:'タグ名を完全一致で検索',exact:true}).fill('v2.0');assert.equal(await tags.locator('tbody tr').count(),1);
  const tagCsv=await download(tags,'表示中をCSV保存');assert.ok(tagCsv.includes('v2.0')&&!tagCsv.includes('v1.0'));
  await tags.locator('.tag-explorer-select').click();await tags.locator('.tag-explorer-annotation pre').waitFor();assert.ok((await tags.locator('.tag-explorer-annotation pre').innerText()).includes('Release notes: feature added.'));
  await tags.locator('.tag-explorer-target').getByText('Extend document',{exact:true}).waitFor();
  await tags.getByRole('searchbox',{name:'タグ名を完全一致で検索',exact:true}).fill('');await tags.getByLabel('タグの並び順').selectOption('name');assert.deepEqual(await tags.locator('.tag-explorer-select strong').allTextContents(),['nightly','v1.0','v2.0']);
  await tags.getByLabel('タグの並び順').selectOption('newest');await capture(tags,'tags');
  await page.route('**/api/repo/tags?**',async route=>{const response=await route.fetch();const data=await response.json();data.tags=data.tags.map(tag=>tag.name==='v2.0'?{...tag,hash:fixture.main,peeled_hash:fixture.main}:tag);await route.fulfill({response,json:data});});
  await tags.getByRole('button',{name:'一覧を更新',exact:true}).click();await tags.locator('.tag-explorer-detail').waitFor({state:'hidden'});assert.equal(await tags.locator('.tag-explorer-detail').count(),0,'refresh must clear a moved tag detail');await page.unroute('**/api/repo/tags?**');
  await tags.locator('summary').first().click();
  passed.push('Tag inventory, exact name search, lightweight/annotated filter, annotation and peeled commit, sorting, filtered CSV');
  const reflog=page.locator('.reflog-explorer');await reflog.locator('summary').first().click();
  await reflog.getByLabel('reflogを調べるref').fill('HEAD');await reflog.getByRole('button',{name:'このrefを調査',exact:true}).click();
  await reflog.locator('.reflog-explorer-table tbody tr').first().waitFor();assert.ok(await reflog.locator('.reflog-explorer-table tbody tr').count()>1);
  await reflog.getByRole('searchbox',{name:'reflogを検索',exact:true}).fill('checkout');
  const checkoutCount=await reflog.locator('.reflog-explorer-table tbody tr').count();assert.ok(checkoutCount>=2);
  const day=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
  await reflog.getByLabel('開始日（ローカル）').fill(day);await reflog.getByLabel('終了日（ローカル）').fill(day);assert.equal(await reflog.locator('.reflog-explorer-table tbody tr').count(),checkoutCount);
  const reflogCsv=await download(reflog,'一致する履歴をCSV保存');assert.ok(reflogCsv.includes('checkout: moving')&&reflogCsv.includes('UI Fixture'));
  await reflog.getByRole('button',{name:'コミットを表示',exact:true}).first().click();await reflog.locator('.reflog-explorer-commit').waitFor();await capture(reflog,'reflog');
  await reflog.getByLabel('開始日（ローカル）').fill('2099-12-31');assert.equal(await reflog.locator('.reflog-explorer-table tbody tr').count(),0);assert.ok(await reflog.getByRole('alert').count()>0);
  await reflog.getByLabel('reflogを調べるref').fill('refs/heads/absent-reference');await reflog.getByRole('button',{name:'このrefを調査',exact:true}).click();await reflog.locator('.reflog-explorer-empty').waitFor();
  await reflog.getByLabel('reflogを調べるref').fill('HEAD');
  const headInventory=await(await page.request.get(`${origin}/api/repo/reflog?path=${encodeURIComponent(fixture.path)}&ref=HEAD`)).json();
  await page.route('**/api/repo/reflog?**',async route=>{await new Promise(resolve=>setTimeout(resolve,250));await route.fulfill({json:headInventory});});
  await reflog.getByRole('button',{name:'このrefを調査',exact:true}).click();await reflog.getByLabel('reflogを調べるref').fill('refs/heads/new-input');await page.waitForTimeout(400);assert.equal(await reflog.locator('.reflog-explorer-table').count(),0,'old response cannot populate a new ref');await page.unroute('**/api/repo/reflog?**');
  await reflog.locator('summary').first().click();passed.push('Reflog explicit ref, search, inclusive local date/error, CSV and target commit detail');

  const compare=page.locator('.commit-compare');await compare.locator('summary').first().click();
  const base=compare.getByLabel('比較元 base のコミットハッシュまたはGit ref'),target=compare.getByLabel('比較先 target のコミットハッシュまたはGit ref');
  await base.fill('main');await target.fill('feature');
  const saved=compare.locator('.investigation-presets');await saved.getByLabel('保存名',{exact:true}).fill('Release check');await saved.getByRole('button',{name:'この入力を保存',exact:true}).click();
  await saved.getByRole('combobox').first().selectOption({label:'Release check'});
  await base.fill('changed-input');await saved.getByRole('button',{name:'開く',exact:true}).click();assert.equal(await base.inputValue(),'main');assert.equal(await compare.locator('.commit-compare-result').count(),0);
  const backup=await download(saved,'JSONバックアップを保存');assert.ok(backup.includes('Release check'));
  await saved.getByRole('button',{name:'比較の共有URLをコピー',exact:true}).click();const share=await clip();assert.ok(share.includes('investigation=compare')&&share.includes('investigationTarget=feature'));
  await capture(compare,'saved-conditions');
  let compareRequests=0;const listener=req=>{if(new URL(req.url()).pathname==='/api/repo/compare')compareRequests++};page.on('request',listener);
  await page.goto(share);await page.waitForFunction(()=>document.querySelector('.commit-compare input[aria-label="比較元 base のコミットハッシュまたはGit ref"]')?.value==='main');
  assert.equal(await target.inputValue(),'feature');assert.ok(await compare.evaluate(el=>el.open));assert.equal(compareRequests,0,'shared URL must not execute');page.off('request',listener);
  await saved.getByRole('combobox').first().selectOption({label:'Release check'});page.once('dialog',dialog=>dialog.accept());await saved.getByRole('button',{name:'削除',exact:true}).click();
  await saved.getByLabel('JSONバックアップを読み込む',{exact:true}).setInputFiles({name:'conditions.json',mimeType:'application/json',buffer:Buffer.from(backup)});
  await saved.getByRole('combobox').first().selectOption({label:'Release check'});
  await saved.getByLabel('JSONバックアップを読み込む',{exact:true}).setInputFiles({name:'invalid.json',mimeType:'application/json',buffer:Buffer.from('{invalid')});await saved.getByRole('alert').waitFor();assert.equal(await base.inputValue(),'main');assert.ok((await saved.getByRole('combobox').first().locator('option').allTextContents()).includes('Release check'));
  await page.goto(projectUrl+'&investigation=compare&investigationBase=main');await compare.locator('summary').first().click();await compare.getByRole('alert').first().waitFor();assert.equal(await base.inputValue(),'');
  await page.goto(projectUrl);const history=page.locator('.file-history-explorer');await history.locator('summary').first().click();
  await history.getByLabel('ファイル履歴のリビジョン').fill('feature');await history.getByLabel('ファイル履歴のファイル相対パス').fill('renamed.txt');await history.getByRole('checkbox',{name:'名前変更を追跡'}).check();
  const historySaved=history.locator('.investigation-presets');await historySaved.getByLabel('保存名',{exact:true}).fill('Rename investigation');await historySaved.getByRole('button',{name:'この入力を保存',exact:true}).click();
  await historySaved.getByRole('button',{name:'ファイル履歴の共有URLをコピー',exact:true}).click();const historyShare=await clip();
  let historyRequests=0;const historyListener=req=>{if(new URL(req.url()).pathname==='/api/repo/file-history')historyRequests++};page.on('request',historyListener);
  await page.goto(historyShare);await page.waitForFunction(()=>document.querySelector('[aria-label="ファイル履歴のファイル相対パス"]')?.value==='renamed.txt');assert.equal(await history.getByLabel('ファイル履歴のリビジョン').inputValue(),'feature');assert.equal(historyRequests,0);page.off('request',historyListener);
  await page.getByRole('combobox',{name:'表示テーマ'}).selectOption('dark');await capture(history,'history-share-dark');
  const storageKey='gitdash.investigation-presets.v1:'+encodeURIComponent(fixture.path);
  const validStore=await page.evaluate(key=>localStorage.getItem(key),storageKey);await page.evaluate(key=>localStorage.setItem(key,'{broken'),storageKey);
  await page.reload();await historySaved.getByRole('alert').first().waitFor();await historySaved.getByLabel('保存名',{exact:true}).fill('Must not overwrite');await historySaved.getByRole('button',{name:'この入力を保存',exact:true}).click();
  assert.equal(await page.evaluate(key=>localStorage.getItem(key),storageKey),'{broken');assert.equal(await history.getByLabel('ファイル履歴のファイル相対パス').inputValue(),'renamed.txt');await page.evaluate(({key,raw})=>localStorage.setItem(key,raw),{key:storageKey,raw:validStore});
  passed.push('Named investigation save/reopen, JSON backup/restore and invalid import preservation, compare/history URL prefill without execution, invalid URL diagnostics');
  assert.deepEqual(errors,[]);await fs.writeFile(`${output}/result.json`,JSON.stringify({origin,fixture:fixture.path,passed,errors},null,2));console.log({passed,errors});
 }catch(e){console.error(e);console.error(await page.evaluate(()=>({width:innerWidth,scroll:document.documentElement.scrollWidth,overflow:[...document.querySelectorAll('body *')].filter(el=>{if(el.getBoundingClientRect().right<=innerWidth+1)return false;for(let a=el.parentElement;a&&a!==document.body;a=a.parentElement){if(['auto','scroll','hidden','clip'].includes(getComputedStyle(a).overflowX))return false;}return true;}).map(el=>({tag:el.tagName,cls:el.className,right:el.getBoundingClientRect().right})).slice(0,25)})));await page.screenshot({path:`${output}/failure.png`});console.error((await page.locator('body').innerText()).slice(-2500));process.exitCode=1;}finally{await browser.close();}
})();
